#!/usr/bin/env node
// Fetches up to 2 well-known people per deck name from Wikidata (E16b). Never generated by AI.
//
//   node scripts/names-content/fetch-people.mjs            # every name in name-content.json
//   node scripts/names-content/fetch-people.mjs --missing  # only names with no people yet
//
// Needs network access to query.wikidata.org. The cloud sandbox and the device VM are blocked,
// so the 2026-11-13 run used the same queries and rules from a query.wikidata.org browser tab.
// Writes data/names/content-src/people.json; build-content.mjs then puts the people on the cards.
//
// Rules (E16 spec §8 + owner 2026-11-13):
// - Candidates, all with a Hebrew Wikipedia article, a Hebrew label that starts with the name and a
//   Hebrew description:
//   1. humans whose given name (P735) is an item with this exact Hebrew label (top 10 by sitelinks);
//   2. for names with 10+ of those, also the top 30 Israeli citizens (P27 Q801) among them, so famous
//      foreigners don't crowd out the people Israeli users know;
//   3. for names still short of 2 people, Israeli humans found by Wikidata search on the Hebrew
//      label (inlabel:"<name>@he" haswbstatement:P27=Q801), for names whose given-name item is
//      missing or unlinked.
// - Excluded: politicians (any subclass of Q82955), anyone who held a position (P39) or has a party
//   (P102), military (personnel, officers, soldiers, a branch P241 or rank P410), diplomats,
//   activists, criminals, anyone convicted (P1399), adult-film performers, every QID in
//   people-exclude.json, and descriptions that tie the person to violence, crime, terror,
//   abduction, war or politics (DESC_BLOCK) - not suitable for a baby-names app.
// - Ranking: Israelis first (citizenship P27 Israel, or "ישראלי" in the description), then by
//   Hebrew Wikipedia page views over the last 60 days (for names with more than 2 eligible people),
//   then number of Wikipedia sitelinks. The description becomes the one-line "what"; a long one is cut
//   at its first clause (Wikidata words only, nothing added). A label that starts with a longer deck
//   name ("בת שבע") is left to that name. The owner and reviewer exclusions (with reasons) live in
//   people-exclude.json; the 2026-11-13 run also had every pick read by hand before it was saved.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const srcDir = resolve(root, "data/names/content-src");
const ENDPOINT = "https://query.wikidata.org/sparql";
const UA = "NestNamesContent/1.0 (https://nestjourney.app; name cards, CC0 data)";
const PER_NAME = 2;

export const DESC_BLOCK =
  /נחטפ|נחטף|חטוף|חטופ|בשבי|שבי |שורד|ערובה|רעיית|בנו של|בתו של|ראש ממשלת|רצח|הוצא להורג|נורה|נהרג|הרוג|נפל ב|חלל צה|פיגוע|טרור|מחבל|פשע|עבריי|הורשע|אסיר|בכלא|נאצי|פורנו|מאפיה|ריגול|ריגל|מרגל|קורבן|נספ|ניצול|פוליטי|חבר הכנסת|חברת הכנסת|ח"כ|ח״כ|(^|\s)שר(ת)?\s|ראש הממשלה|ראש עיר|ראש העיר|ראש מועצ|ראש המועצ|מפלג|דיפלומט|שגריר|קצין|קצינ|תא"ל|תת-אלוף|אלוף משנה|רב-אלוף|לוחם|לוחמת|מפקד|צבא|צה"ל|צה״ל|מערכת הביטחון|שב"כ|פעיל|אקטיביסט|מחאה|מתנחל|מיסיונר|(^|\s)כת\s|נוכל|הונאה|בית המשפט העליון|הסכמי אוסלו|טבח|7 באוקטובר|(^|\s)(בנו|בתו|בנה|בתה|אשתו)\s|נכדת?ו |אחיו של|אחותו של|בתם של|בנם של|לוחמי|מתקפת הפתע|מוסד|יועץ התקשורת של|ארץ ישראל השלמה|עורך דין של|נתניהו/;
const BAD_OCCUPATION_ROOTS = ["Q82955", "Q47064", "Q4991371", "Q189290", "Q193391", "Q15253558", "Q2159907", "Q488111", "Q12900932"];

// Tidies a Wikidata description into the card's "what" line: whitespace, a trailing dot, a leading
// "היה" or "<label> היא", and a long one cut at its first clause (Wikidata words only, nothing added).
export function trimWhat(desc, label = "") {
  let d = desc.replace(/\s+/g, " ").replace(/\\"/g, '"').trim().replace(/\.$/, "");
  d = d.replace(/^היה /, "");
  if (label && d.startsWith(label + " היא ")) d = d.slice(label.length + 5);
  if (d.length <= 55) return d;
  const cut = d.split(/[,;(]|\.\s/)[0].trim();
  return cut.length >= 6 ? cut : d;
}

// Drops a disambiguation suffix such as "סטיב קפלן (כדורסלן)".
export const cleanLabel = (label) => label.replace(/\s*\([^)]*\)$/, "").replace(/\s+/g, " ").trim();

// A person whose label starts with a longer deck name ("בת שבע", "בת חן") belongs to that name, not to "בת".
export function belongsToLonger(name, label, deckNames) {
  const longer = deckNames.filter((d) => d !== name && (d.startsWith(name + " ") || d.startsWith(name + "-")));
  return longer.some((d) => label === d || label.startsWith(d + " "));
}

export function eligible(name, candidates, props, bad, exclude, deckNames = []) {
  const ok = [];
  const seen = new Set();
  for (const c of candidates) {
    if (seen.has(c.qid)) continue;
    seen.add(c.qid);
    const p = props[c.qid] ?? {};
    if (!(p.P31 ?? []).includes("Q5")) continue;
    if (exclude.has(c.qid)) continue;
    if (p.P39 || p.P1399 || p.P102 || p.P241 || p.P410) continue;
    if ((p.P106 ?? []).some((o) => bad.has(o))) continue;
    if (!(c.label === name || c.label.startsWith(name + " "))) continue;
    if (belongsToLonger(name, c.label, deckNames)) continue;
    if (!c.desc || c.desc.trim() === c.label.trim() || DESC_BLOCK.test(c.desc)) continue;
    const israeli = (p.P27 ?? []).includes("Q801") || /ישראלי/.test(c.desc);
    ok.push({ ...c, israeli });
  }
  return ok.sort((a, b) => Number(b.israeli) - Number(a.israeli) || b.links - a.links);
}

// Final order: Israelis first, then Hebrew Wikipedia page views (last 60 days) when known, then sitelinks.
export function rank(list, views = {}) {
  return [...list]
    .sort((a, b) => Number(b.israeli) - Number(a.israeli) || (views[b.qid] ?? -1) - (views[a.qid] ?? -1) || b.links - a.links)
    .slice(0, PER_NAME)
    .map((c) => ({ name: cleanLabel(c.label), what: trimWhat(c.desc, c.label), qid: c.qid }));
}

async function sparql(query, attempt = 1) {
  const res = await fetch(ENDPOINT, {
    method: "POST",
    headers: { "User-Agent": UA, Accept: "application/sparql-results+json", "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ query }),
  });
  if (res.ok) return (await res.json()).results.bindings;
  if (attempt < 5 && (res.status === 429 || res.status >= 500)) {
    await new Promise((r) => setTimeout(r, 4000 * attempt));
    return sparql(query, attempt + 1);
  }
  throw new Error(`Wikidata ${res.status}: ${(await res.text()).slice(0, 300)}`);
}

const candidatesQuery = (chunk) => `
SELECT ?name ?person ?label ?desc ?links WHERE {
  VALUES ?name { ${chunk.map((n) => JSON.stringify(n) + "@he").join(" ")} }
  ?gn rdfs:label ?name ; wdt:P31 ?gnType .
  VALUES ?gnType { wd:Q202444 wd:Q12308941 wd:Q11879590 wd:Q3409032 }
  ?person wdt:P735 ?gn .
  ?article schema:about ?person ; schema:isPartOf <https://he.wikipedia.org/> .
  ?person wikibase:sitelinks ?links ; rdfs:label ?label . FILTER(LANG(?label) = "he")
  OPTIONAL { ?person schema:description ?desc . FILTER(LANG(?desc) = "he") }
}`;
const propsQuery = (qids) => `
SELECT ?p ?prop ?val WHERE {
  VALUES ?p { ${qids.map((q) => "wd:" + q).join(" ")} }
  VALUES ?prop { wdt:P31 wdt:P27 wdt:P106 wdt:P39 wdt:P1399 wdt:P569 wdt:P570 wdt:P241 wdt:P410 wdt:P102 }
  ?p ?prop ?val }`;
const israeliQuery = (n) => `
SELECT ?person ?label ?desc ?links WHERE {
  ?gn rdfs:label ${JSON.stringify(n)}@he ; wdt:P31 ?gnType .
  VALUES ?gnType { wd:Q202444 wd:Q12308941 wd:Q11879590 wd:Q3409032 }
  ?person wdt:P735 ?gn ; wdt:P27 wd:Q801 .
  ?article schema:about ?person ; schema:isPartOf <https://he.wikipedia.org/> .
  ?person wikibase:sitelinks ?links ; rdfs:label ?label . FILTER(LANG(?label) = "he")
  ?person schema:description ?desc . FILTER(LANG(?desc) = "he")
} ORDER BY DESC(?links) LIMIT 30`;
const infoQuery = (qids) => `
SELECT ?p ?label ?desc ?links WHERE {
  VALUES ?p { ${qids.map((q) => "wd:" + q).join(" ")} }
  ?article schema:about ?p ; schema:isPartOf <https://he.wikipedia.org/> .
  ?p wikibase:sitelinks ?links ; rdfs:label ?label . FILTER(LANG(?label) = "he")
  OPTIONAL { ?p schema:description ?desc . FILTER(LANG(?desc) = "he") }
}`;
const local = (uri) => uri.split("/").pop();

async function main() {
  const readJson = (file) => JSON.parse(readFileSync(file, "utf8"));
  const missing = process.argv.includes("--missing");
  const peopleFile = resolve(srcDir, "people.json");
  const previous = existsSync(peopleFile) ? readJson(peopleFile).names : {};
  const deck = readJson(resolve(root, "data/names/name-content.json")).names;
  const deckNames = Object.keys(deck);
  const names = deckNames.filter((n) => !missing || !(deck[n].people?.length || previous[n]?.length));
  const exclude = new Set(readJson(resolve(srcDir, "people-exclude.json")).qids.map((q) => q.qid));

  const bad = new Set();
  for (const rootQ of BAD_OCCUPATION_ROOTS) {
    for (const b of await sparql(`SELECT ?o WHERE { ?o wdt:P279* wd:${rootQ} }`)) bad.add(local(b.o.value));
  }

  const cands = {};
  for (let i = 0; i < names.length; i += 20) {
    for (const b of await sparql(candidatesQuery(names.slice(i, i + 20)))) {
      (cands[b.name.value] ??= []).push({ qid: local(b.person.value), label: b.label.value, desc: b.desc?.value ?? "", links: Number(b.links.value) });
    }
    console.log(`candidates ${Math.min(i + 20, names.length)}/${names.length}`);
  }
  for (const n of Object.keys(cands)) {
    const seen = new Set();
    cands[n] = cands[n]
      .filter((c) => c.desc && (c.label === n || c.label.startsWith(n + " ")))
      .sort((a, b) => b.links - a.links)
      .filter((c) => !seen.has(c.qid) && seen.add(c.qid))
      .slice(0, 10);
  }
  // Pass 2: Israelis first for common names.
  for (const n of names.filter((x) => (cands[x]?.length ?? 0) >= 10)) {
    for (const b of await sparql(israeliQuery(n))) {
      cands[n].push({ qid: local(b.person.value), label: b.label.value, desc: b.desc.value, links: Number(b.links.value) });
    }
  }
  const props = {};
  const loadProps = async (qids) => {
    const todo = qids.filter((q) => !props[q]);
    for (let i = 0; i < todo.length; i += 100) {
      for (const b of await sparql(propsQuery(todo.slice(i, i + 100)))) {
        ((props[local(b.p.value)] ??= {})[local(b.prop.value)] ??= []).push(local(b.val.value));
      }
    }
  };
  await loadProps([...new Set(Object.values(cands).flat().map((c) => c.qid))]);

  // Pass 3: Wikidata search for Israelis whose Hebrew label starts with the name.
  const short = names.filter((n) => eligible(n, cands[n] ?? [], props, bad, exclude, deckNames).length < PER_NAME);
  for (const n of short) {
    const url = `https://www.wikidata.org/w/api.php?action=query&list=search&srlimit=50&srprop=&format=json&srsearch=${encodeURIComponent(`inlabel:"${n}@he" haswbstatement:P27=Q801 haswbstatement:P31=Q5`)}`;
    const hits = ((await (await fetch(url, { headers: { "User-Agent": UA } })).json()).query?.search ?? []).map((h) => h.title);
    if (!hits.length) continue;
    for (const b of await sparql(infoQuery(hits))) {
      (cands[n] ??= []).push({ qid: local(b.p.value), label: b.label.value, desc: b.desc?.value ?? "", links: Number(b.links.value) });
    }
    await loadProps(hits);
  }

  // Page views decide between more than 2 eligible people (top 4 by sitelinks each).
  const lists = Object.fromEntries(names.map((n) => [n, eligible(n, cands[n] ?? [], props, bad, exclude, deckNames)]));
  const views = {};
  const toCheck = [...new Set(Object.values(lists).filter((l) => l.length > PER_NAME).flatMap((l) => l.slice(0, 4).map((c) => c.qid)))];
  for (let i = 0; i < toCheck.length; i += 50) {
    const titles = {};
    for (const b of await sparql(`SELECT ?p ?a WHERE { VALUES ?p { ${toCheck.slice(i, i + 50).map((q) => "wd:" + q).join(" ")} } ?a schema:about ?p ; schema:isPartOf <https://he.wikipedia.org/> }`)) {
      titles[decodeURIComponent(b.a.value.split("/wiki/")[1]).replace(/_/g, " ")] = local(b.p.value);
    }
    let cont = {};
    for (let guard = 0; cont && guard < 20; guard++) {
      const params = new URLSearchParams({ action: "query", prop: "pageviews", titles: Object.keys(titles).join("|"), format: "json", formatversion: "2", pvipdays: "60", ...cont });
      const j = await (await fetch(`https://he.wikipedia.org/w/api.php?${params}`, { headers: { "User-Agent": UA } })).json();
      for (const page of j.query?.pages ?? []) {
        if (page.pageviews && titles[page.title]) views[titles[page.title]] = Object.values(page.pageviews).reduce((s, v) => s + (v ?? 0), 0);
      }
      cont = j.continue ?? null;
    }
  }

  const out = { ...previous };
  for (const n of names) out[n] = rank(lists[n], views);
  writeFileSync(
    peopleFile,
    JSON.stringify(
      {
        _about:
          "Known people per name, from Wikidata (CC0) by scripts/names-content/fetch-people.mjs. Do not add people by hand; to remove one, add the QID to people-exclude.json and run the script again.",
        fetchedAt: new Date().toISOString().slice(0, 10),
        names: Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b, "he"))),
      },
      null,
      1,
    ) + "\n",
  );
  console.log(`Wrote ${peopleFile}`);
}

if (import.meta.url === `file://${process.argv[1]}`) await main();
